package com.rushi.walletledger.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.PrePersist;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.UUID;

/**
 * One money movement, identified by the idempotency key of the HTTP request that caused it.
 * The id is a UUID generated by the application so the result of a request can be returned
 * (and replayed from the idempotency key) without depending on a database round trip.
 *
 * <p>There is deliberately no collection of entries mapped here: entries are read through
 * {@link LedgerEntry} queries, so nothing lazy-loads behind a controller.
 */
@Entity
@Table(name = "ledger_transactions")
public class LedgerTransaction {

    @Id
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @Column(name = "idempotency_key", nullable = false, updatable = false)
    private String idempotencyKey;

    /** SHA-256 of the normalised request body, used to tell a replay from a key misuse. */
    @Column(name = "request_hash", nullable = false, updatable = false)
    private String requestHash;

    @Enumerated(EnumType.STRING)
    @Column(name = "type", nullable = false)
    private TransactionType type;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false)
    private TransactionStatus status;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt;

    /** Required by JPA. */
    protected LedgerTransaction() {
    }

    private LedgerTransaction(UUID id,
                              String idempotencyKey,
                              String requestHash,
                              TransactionType type) {
        this.id = id;
        this.idempotencyKey = idempotencyKey;
        this.requestHash = requestHash;
        this.type = type;
        this.status = TransactionStatus.POSTED;
    }

    public static LedgerTransaction posted(UUID id,
                                           String idempotencyKey,
                                           String requestHash,
                                           TransactionType type) {
        return new LedgerTransaction(id, idempotencyKey, requestHash, type);
    }

    @PrePersist
    void assignCreatedAt() {
        if (createdAt == null) {
            createdAt = Instant.now();
        }
    }

    public UUID getId() {
        return id;
    }

    public String getIdempotencyKey() {
        return idempotencyKey;
    }

    public String getRequestHash() {
        return requestHash;
    }

    public TransactionType getType() {
        return type;
    }

    public TransactionStatus getStatus() {
        return status;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }
}
